export type StudioLocale = 'ja' | 'en'

export type MessageParams = Record<string, string | number | null | undefined>

export interface MessageDefinition {
  ja: string
  en: string
}

/**
 * A feature catalogue is deliberately kept in source control rather than in
 * the DOM.  Message IDs are stable API between rendering code and copy, and
 * both locales must be supplied when a message is added.
 */
export function defineMessages<const T extends Record<string, MessageDefinition>>(messages: T): T {
  return messages
}

