  'onboarding.probe.route': { ja: 'チェックを入れると自動で Step 2（ファーム書き込み）へ進みます。複数チェックすれば同時書き込みもできます。', en: 'Checking a device automatically continues to Step 2 (flash firmware). You can flash multiple checked devices together.' },
  'onboarding.probe.note': { ja: '※「⚙ 設定」ボタンは書き込み後の Wi-Fi 設定用です（初回書き込みには不要）。既にファーム入りのデバイスを設定だけしたいときは「⚙ 設定」で接続すると Step 3 へ直行します。', en: '⚙ Settings is for Wi-Fi setup after flashing, not initial flashing. To configure an already flashed device, connect with ⚙ Settings to go straight to Step 3.' },
  'onboarding.flash.title': { ja: 'Step 2 — ファームウェア書き込み', en: 'Step 2 — Flash firmware' },
  'onboarding.flash.intro': { ja: '下のファームウェアライブラリでノードの種類（Hapbeat / 周辺機器）を選び、書き込むファームウェアを選んで「Serial 書き込み」を押してください。', en: 'In the firmware library below, choose the node type (Hapbeat / peripheral), select firmware, then press Serial write.' },
  'onboarding.flash.next': { ja: '👉 書き込み完了後、自動で Step 3（Wi-Fi 設定）に進みます。その後デバイスの電源を一度 OFF→ON してから、左の USB Serial カードの「⚙ 設定」ボタンで設定接続してください。', en: '👉 After flashing, Studio continues to Step 3 (Wi-Fi setup). Power the device OFF then ON, then use ⚙ Settings on its USB Serial card to connect for configuration.' },
  'onboarding.backToStep1': { ja: '← Step 1 に戻る', en: '← Back to Step 1' },
  'onboarding.configure.waitTitle': { ja: 'Step 3 — Wi-Fi 設定（再接続待ち）', en: 'Step 3 — Wi-Fi setup (waiting to reconnect)' },
  'onboarding.configure.waitIntro': { ja: 'ファーム書き込みが完了しました。デバイスの電源を一度 OFF→ON してから、左の USB Serial カードの「⚙ 設定」ボタンで設定接続してください（接続中はカード枠が緑になります）。', en: 'Flashing is complete. Power the device OFF then ON, then use ⚙ Settings on its USB Serial card to connect for configuration (the card border turns green).' },
  'onboarding.configure.waitNote': { ja: '設定接続できたら設定タブの Wi-Fi セクションで SSID / パスワードを入力できます。', en: 'Once connected for configuration, enter the SSID and password in the Wi-Fi section.' },
  'onboarding.configure.title': { ja: 'Step 3 — Wi-Fi 設定へ進む', en: 'Step 3 — Continue to Wi-Fi setup' },
  'onboarding.configure.intro': { ja: 'シリアル接続できました。下のボタンで Wi-Fi 設定タブに進み、SSID とパスワードを登録してください。Wi-Fi 接続が確立するとデバイスが LAN 上に表示され、設定タブからデバイス識別 / UI Config / Debug Dump にアクセスできます。', en: 'Serial configuration is connected. Open the Wi-Fi tab below and register the SSID and password. Once Wi-Fi connects, the device appears on the LAN and its settings tab provides device identity, UI Config, and Debug Dump.' },
  'onboarding.configure.openTitle': { ja: 'DeviceDetail の Wi-Fi タブを開きます', en: 'Open the DeviceDetail Wi-Fi tab' },
  'onboarding.configure.open': { ja: 'Wi-Fi 設定タブへ進む →', en: 'Open Wi-Fi setup →' },
  'onboarding.configure.disconnect': { ja: '切断して Step 1 に戻る', en: 'Disconnect and return to Step 1' },
