  'devices.usb.selectTitle': { ja: 'クリック=書き込み対象に選択 / Ctrl+クリック=追加 / Shift+クリック=範囲選択。選択だけでは接続しません。設定・Wi-Fi は「設定」から接続します。', en: 'Click: select flash target / Ctrl-click: add / Shift-click: range. Selection does not connect; use Settings for config and Wi-Fi.' },
  'devices.usb.closeTitle': { ja: 'このカードを閉じる（COM ポートの許可を取り消す）。通常は不要です。誤って追加した非 Hapbeat COM ポートを削除する場合のみ使います。', en: 'Close this card and revoke COM-port permission. Normally unnecessary; use only to remove a mistakenly added non-Hapbeat port.' },
  'devices.usb.probeTitle': { ja: 'get_info で名前・ファームウェア等を取得し、書き込み完了表示も消去します。S3 (DuoWL v3/v4) は USB 切断時に再起動します。', en: 'Fetch name, firmware, and more with get_info; also clears the completed-flash state. S3 (DuoWL v3/v4) restarts when USB disconnects.' },
  'firmware.parallelFlashHint': { ja: '別のファームを別デバイスへ同時に書く場合は、片方の書き込み開始後に別のファームとデバイスを選び、もう一度書き込みます。', en: 'To flash different firmware to another device in parallel, start the first flash, then select the other firmware and device and flash again.' },
